// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint96 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0);
        address actor = address(0xBEEF);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        uint256 cBalanceBefore = address(c).balance;
        vm.prank(actor);
        c.withdrawBalance();
        // The reference refunds exactly `amount`; the mutant refunds 0.
        // So the contract's balance decreases by `amount` in the reference, but not in the mutant.
        assertTrue(cBalanceBefore - address(c).balance == amount);
    }
}
